public class TypeDemonstration {
    public static void main(String[] args) {
        // Primitive Type: Stored directly on the stack
        int primitiveAge = 30;
        int anotherPrimitive = primitiveAge;
        anotherPrimitive = 35;
        System.out.println(primitiveAge); // Outputs 30 (independent copy)

        // Reference Type: Stack stores pointer, heap stores object data
        int[] primitiveArray = {1, 2, 3};
        int[] referenceAssignment = primitiveArray;
        referenceAssignment[0] = 99;
        System.out.println(primitiveArray[0]); // Outputs 99 (shared heap reference)

        // Autoboxing trap in a loop
        Long sum = 0L;
        for (long i = 0; i < 1_000_000L; i++) {
            sum += i; // Implicitly creates a new Long object on every iteration!
        }
    }
}
